using System;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckBaseJumping {public sealed class BaseSplitViewSmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> records=new List<string>();SportsTestPreferences prefs;BaseJumpMatch m;Keyboard keyboard;InputSettings original,probe;string folder;bool done,error;
 [RuntimeInitializeOnLoadMethod]static void Boot(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsBaseSplit")<0)return;var go=new GameObject("Four-view canopy rendering validation");DontDestroyOnLoad(go);go.AddComponent<BaseSplitViewSmoke>();}
 void Start(){prefs=new SportsTestPreferences();folder=LWS.TruckSports.SportsEvidencePaths.Folder("SplitViewEvidence");Directory.CreateDirectory(folder);original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Split-view software keyboard");InputSystem.QueueStateEvent(keyboard,new KeyboardState());Application.logMessageReceived+=Log;steps.Push(Run());}
 void Log(string s,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){error=true;records.Add("ERROR "+s);}}void Check(bool b,string label){if(!b)throw new Exception(label);records.Add("PASS "+label);Debug.Log("BASE_SPLIT_PASS "+label);}IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}
 void Update(){if(done)return;if(m!=null&&m.Live&&m.Phase==BaseJumpPhase.Flight)for(int i=0;i<4;i++){var j=m.jumpers[i];if(!j.Deployed&&j.truck.body.position.y<225)m.actions[i]=true;var p=j.truck.body.position;var desired=Vector2.ClampMagnitude(new Vector2(-p.x,-p.z)*.2f,8);float coupling=Mathf.Lerp(.18f,.65f,j.Opening),power=Mathf.Lerp(3.2f,8.5f,j.Opening);m.commands[i]=Vector2.ClampMagnitude((desired-new Vector2(m.weatherField.Flow.x,m.weatherField.Flow.z))*coupling/power,1);}try{while(steps.Count>0){var s=steps.Peek();if(!s.MoveNext()){steps.Pop();continue;}if(s.Current is IEnumerator child){steps.Push(child);continue;}return;}Finish(error?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError(e);Finish(2);}}
 void Finish(int code){done=true;Time.timeScale=1;prefs.Dispose();File.WriteAllLines(Path.Combine(folder,"results.txt"),records);if(keyboard.added)InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;Destroy(probe);Application.Quit(code);}void Capture(string label){ScreenCapture.CaptureScreenshot(Path.Combine(folder,label+".png"));}
 IEnumerator Run(){yield return Delay(.5f);SceneManager.LoadScene("TruckBaseJumping");yield return Delay(.6f);m=FindAnyObjectByType<BaseJumpMatch>();for(int i=0;i<4;i++){m.setup.players[i].source=BowlingSource.Keyboard;m.setup.players[i].name="Long participant "+(i+1);}m.option=2;Check(m.StartMatch(),"four software-source views start");float end=Time.realtimeSinceStartup+18;while(m.jumpers[3].Opening<.99f){if(Time.realtimeSinceStartup>end)throw new Exception("Canopy opening timeout");yield return null;}Check(m.ViewCount==4,"all four canopies and camera views remain active");foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){Screen.SetResolution(size.x,size.y,false);yield return Delay(.4f);for(int i=0;i<4;i++){var label=m.menus.viewTexts[i];label.ForceMeshUpdate();Check(!label.isTextOverflowing,"compact colored HUD text fits "+size.x+" slot"+i);}Capture("four-open-canopies-"+size.x);yield return Delay(.2f);}m.Pause();var p=m.jumpers[0].truck.body.position;var v=m.jumpers[0].truck.body.linearVelocity;yield return Delay(.3f);Check(m.jumpers[0].truck.body.position==p&&m.jumpers[0].truck.body.linearVelocity==v,"pause preserves four deployed canopies and flight");m.Resume();yield return Delay(.2f);SportsNavigation.FrontEnd();yield return Delay(.6f);Check(FindObjectsByType<DigitalRuby.WeatherMaker.WeatherMakerScript>(FindObjectsInactive.Include).Length==0,"scene-owned weather removed after four-view exit");Check(!error,"four-view rendering has no runtime exceptions");}
 void OnDestroy(){Application.logMessageReceived-=Log;}
#endif
}}
